  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Foods, Meals and the Verb Gustar$j$, $j${"readings": [{"title": "Psalm 104 (King James Version)", "url": "/portal/bible/Psalms/104"}], "body": "Psalm 104:14 and 15 say that God causes grass to grow for the cattle and herb for the service of man, that he may bring forth food out of the earth, and bread which strengtheneth man's heart. Food is a gift from God and a way to share friendship.\n\nThe meals of the day are el desayuno for breakfast, el almuerzo for lunch and la cena for dinner. Foods include el pan for bread, la leche for milk, los huevos for eggs, el arroz for rice, los frijoles for beans, el pollo for chicken, la carne for meat, el pescado for fish, el queso for cheese, la sopa for soup, la ensalada for salad, las verduras for vegetables and las frutas for fruit. Fruits include la manzana for apple, la naranja for orange, el plátano for banana and la fresa for strawberry. Drinks include el agua, el jugo, el café and el té.\n\nTo say what you like, Spanish uses the verb gustar, which works like it is pleasing to me. Me gusta means I like when what you like is singular, as in Me gusta el pan. Me gustan means I like when what you like is plural, as in Me gustan las frutas. The other forms are te gusta for you like, le gusta for he or she likes, nos gusta for we like and les gusta for they like. To say you do not like something, put no before: No me gusta el pescado. To ask, say ¿Te gusta la sopa? Answer Sí, me gusta or No, no me gusta. To say you love something, use me encanta.\n\nUseful verbs are comer, beber, desayunar, almorzar and cenar. At home before a meal, many families say a prayer of thanks, called una bendición.\n\nYour task: (1) Write what you eat for each meal in Spanish. (2) Write four sentences with gusta or gustan.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Psalm 104 says God brings forth food out of the earth, and bread which strengtheneth man's heart.\n\nNow watch this. El desayuno is breakfast. El almuerzo is lunch. La cena is dinner. Foods are el pan, la leche, los huevos, el arroz, los frijoles, el pollo, la carne, el pescado, la sopa, la ensalada and las frutas.\n\nSpanish says gustar for like. Me gusta el pan, for one thing. Me gustan las frutas, for plural things. Te gusta means you like. Le gusta means he or she likes. No me gusta means I do not like it. Me encanta means I love it.\n\nYour task is to write your meals and four sentences with gusta or gustan. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Foods, Meals and the Verb Gustar$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 At the Restaurant and Stem Changing Verbs$j$, $j${"readings": [{"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}], "body": "Proverbs 15:17 says, Better is a dinner of herbs where love is, than a stalled ox and hatred therewith. A meal is best when it is shared in love, and a restaurant is a great place to practice Spanish.\n\nSome Spanish verbs change their stem vowel in most forms but not in the nosotros form. These are called stem changing verbs. Querer, which means to want, changes e to ie: quiero, quieres, quiere, queremos, quieren. Preferir, which means to prefer, works the same way: prefiero, prefieres, prefiere, preferimos, prefieren. Poder, which means to be able or can, changes o to ue: puedo, puedes, puede, podemos, pueden. Almorzar, which means to eat lunch, also changes o to ue: almuerzo, almuerzas, almuerza, almorzamos, almuerzan. Pedir, which means to order or ask for, changes e to i: pido, pides, pide, pedimos, piden. Dormir, which means to sleep, is duermo, duermes, duerme, dormimos, duermen.\n\nA restaurant conversation uses polite phrases. The waiter may say ¿Qué desea usted? or ¿Qué quieren tomar? You may answer Quisiera una sopa, por favor, which means I would like a soup, please, or Quiero el pollo con arroz. To ask for the bill, say La cuenta, por favor. To say it was delicious, say Está delicioso or Está muy rico. Say gracias and leave a kind word for the server.\n\nVerbs like querer and poder are often followed by an infinitive: Quiero comer, Puedo ayudar, Prefiero beber agua.\n\nYour task: (1) Conjugate querer and poder. (2) Write a short restaurant dialogue with at least six lines.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Proverbs 15:17 says, Better is a dinner of herbs where love is, than a stalled ox and hatred therewith.\n\nNow watch this. Some verbs change the stem vowel in every form except nosotros. Querer, e to ie. Quiero, quieres, quiere, queremos, quieren. Poder, o to ue. Puedo, puedes, puede, podemos, pueden. Pedir, e to i. Pido, pides, pide, pedimos, piden.\n\nAt the restaurant, say quisiera una sopa, por favor. Say quiero el pollo con arroz. Ask for the bill with la cuenta, por favor. Say está delicioso.\n\nAfter querer or poder, use an infinitive. Quiero comer. Puedo ayudar.\n\nYour task is to conjugate querer and poder and write a restaurant dialogue. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 At the Restaurant and Stem Changing Verbs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Clothing, Colors, Shopping and Larger Numbers$j$, $j${"readings": [{"title": "Proverbs 31 (King James Version)", "url": "/portal/bible/Proverbs/31"}], "body": "Proverbs 31:22 describes a virtuous woman who maketh herself coverings of tapestry; her clothing is silk and purple. Clothing and shopping are part of daily life, and knowing prices and numbers helps you shop wisely.\n\nClothing words include la camisa for shirt, los pantalones for pants, el vestido for dress, la falda for skirt, la chaqueta for jacket, los zapatos for shoes, los calcetines for socks, el sombrero for hat and la ropa for clothes. Colors are adjectives that agree with the noun: rojo, azul, verde, amarillo, negro, blanco, gris, rosado and morado. La camisa roja, los zapatos negros.\n\nTo ask a price, say ¿Cuánto cuesta? for one item and ¿Cuánto cuestan? for more than one. Cuesta veinte dólares. The verb costar is a stem changing verb with o to ue. Shop with phrases like Necesito una talla mediana, which means I need a medium size, ¿Tiene esto en azul? and Es muy caro, which means it is very expensive. The opposite is barato for cheap.\n\nNumbers above one hundred are cien for 100, ciento uno for 101, doscientos for 200, trescientos for 300, cuatrocientos for 400, quinientos for 500, seiscientos for 600, setecientos for 700, ochocientos for 800, novecientos for 900 and mil for 1000. The hundreds agree with feminine nouns, so we say doscientas camisas. Note that quinientos is irregular. Prices are read as full numbers, so 250 is doscientos cincuenta.\n\nShop with wisdom. Proverbs 21:20 says, There is treasure to be desired and oil in the dwelling of the wise.\n\nYour task: (1) Write the numbers 100, 250, 500 and 1000 in Spanish. (2) Write a short shopping dialogue.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Proverbs 31:22 speaks of clothing of silk and purple. Shopping is part of daily life, and wise shopping is part of stewardship.\n\nNow watch this. La camisa, los pantalones, el vestido, la falda, la chaqueta, los zapatos. Colors agree with the noun. La camisa roja. Los zapatos negros.\n\nAsk the price. ¿Cuánto cuesta? or ¿Cuánto cuestan? Cuesta veinte dólares. Es muy caro. Es barato.\n\nLarger numbers. Cien. Doscientos. Trescientos. Cuatrocientos. Quinientos. Seiscientos. Setecientos. Ochocientos. Novecientos. Mil. With feminine nouns, say doscientas camisas.\n\nYour task is to write four numbers and a shopping dialogue. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Clothing, Colors, Shopping and Larger Numbers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Places in Town, the Verb Ir and Directions$j$, $j${"readings": [{"title": "Luke 10 (King James Version)", "url": "/portal/bible/Luke/10"}], "body": "In Luke 10:36 and 37, Jesus asked which of three men was neighbour unto him that fell among the thieves, and the answer was, He that shewed mercy on him. Then said Jesus, Go, and do thou likewise. Knowing the places in your town and how to give directions helps you be a good neighbor.\n\nPlaces include la iglesia for church, el banco for bank, el supermercado for supermarket, la tienda for store, el parque for park, el hospital for hospital, la farmacia for pharmacy, la biblioteca for library, el restaurante for restaurant, la escuela for school, el correo for post office and la playa for beach.\n\nThe verb ir means to go. It is irregular: voy, vas, va, vamos, van. It is followed by a, which means to or at. Voy a la iglesia. Vamos al parque. When a is followed by el, the two words combine into al, as in Voy al banco. When de is followed by el, they combine into del, as in Vengo del hospital. Ir a plus an infinitive means to be going to, as in Voy a estudiar. Use ¿Adónde vas? to ask where you are going.\n\nFor directions, use ¿Dónde está la farmacia? and answers like Está a la derecha for to the right, Está a la izquierda for to the left, Sigue derecho for go straight, Dobla a la derecha for turn right, Cruza la calle for cross the street, Está cerca de for near, Está lejos de for far from, Está al lado de for next to, Está enfrente de for in front of, and Está entre for between.\n\nYour task: (1) Conjugate ir. (2) Write directions in Spanish from the church to the park. (3) Write four sentences with ir a.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Luke 10:37 says, Go, and do thou likewise. Knowing your town and how to give directions helps you be a good neighbor.\n\nNow watch this. La iglesia, el banco, el supermercado, la tienda, el parque, el hospital, la farmacia, la biblioteca, el restaurante, la escuela, el correo.\n\nIr means to go. Voy, vas, va, vamos, van. Voy a la iglesia. A plus el becomes al. Vamos al parque. De plus el becomes del. Voy a estudiar means I am going to study.\n\nFor directions, ask ¿Dónde está la farmacia? Answer a la derecha, a la izquierda, sigue derecho, dobla a la derecha, cruza la calle. Use cerca de, lejos de, al lado de, enfrente de and entre.\n\nYour task is to conjugate ir, write directions and four sentences with ir a. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Places in Town, the Verb Ir and Directions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Food, Shopping and Community$j$, $j${"prompt": "Write a report of at least 250 words in English with Spanish examples. Use complete sentences and label each part. Luke 10:37 says, Go, and do thou likewise.\n\nPart 1: List the three meals and ten foods and drinks in Spanish. Explain how gustar works and write six sentences using me gusta, me gustan, te gusta and no me gusta.\nPart 2: Explain stem changing verbs and conjugate querer, poder and pedir. Write a restaurant dialogue of at least eight lines.\nPart 3: Write the numbers 100, 200, 300, 500, 700 and 1000 in Spanish and write a shopping dialogue that includes a price, a color and a size.\nPart 4: Conjugate ir, explain al and del, and write directions in Spanish from your school to a church or park.\nPart 5: Explain how Luke 10:36 and 37 and Proverbs 15:17 guide you in being a neighbor and in sharing a meal.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 20 points. Part 4: 25 points. Part 5: 5 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Food, Shopping and Community$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Go, and Do Thou Likewise$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a food from a Spanish speaking culture that you have eaten or would like to try, using at least three Spanish words from this unit, (2) explains one way you could be a good neighbor to a Spanish speaking family or visitor in your community, such as giving directions or sharing a meal, (3) tells why hospitality matters in the church, and (4) connects your answer to Luke 10:36 and 37, Proverbs 15:17 or Psalm 104:14 and 15. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What does it mean to show hospitality without expecting anything in return? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Go, and Do Thou Likewise$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Foods, Meals and the Verb Gustar$j$, $j${"questions": [{"q": "El almuerzo is:", "options": ["Lunch", "Dinner", "Snack", "Breakfast"]}, {"q": "Me gustan las frutas means:", "options": ["I like fruits", "I buy fruit", "I have fruit", "I eat fruit"]}, {"q": "Which is correct?", "options": ["Me gusto el pollo", "Me gustan el pollo", "Yo gusto el pollo", "Me gusta el pollo"]}, {"q": "La leche is:", "options": ["Soup", "Milk", "Cheese", "Bread"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Foods, Meals and the Verb Gustar$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,1}'::int[], array[$j$Almuerzo means lunch.$j$,$j$Gustan is plural because frutas is plural.$j$,$j$One thing liked uses gusta.$j$,$j$Leche is milk.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Foods, Meals and the Verb Gustar$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: At the Restaurant and Stem Changing Verbs$j$, $j${"questions": [{"q": "The yo form of querer is:", "options": ["Quero", "Quiere", "Queremos", "Quiero"]}, {"q": "Nosotros podemos means:", "options": ["We can", "I can", "They can", "You can"]}, {"q": "La cuenta, por favor means:", "options": ["The water, please", "The menu, please", "The soup, please", "The bill, please"]}, {"q": "The yo form of pedir is:", "options": ["Pido", "Pedimos", "Pide", "Pedo"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: At the Restaurant and Stem Changing Verbs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,0}'::int[], array[$j$Querer changes e to ie.$j$,$j$The nosotros form does not change its stem.$j$,$j$Cuenta is bill.$j$,$j$Pedir changes e to i.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: At the Restaurant and Stem Changing Verbs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Clothing, Colors, Shopping and Larger Numbers$j$, $j${"questions": [{"q": "¿Cuánto cuesta? asks:", "options": ["Where is it?", "What color is it?", "When is it?", "How much does it cost?"]}, {"q": "Quinientos is:", "options": ["500", "15", "50", "5000"]}, {"q": "Red shirt in Spanish is:", "options": ["La camisa roja", "El camisa roja", "La roja camisa", "La camisa rojo"]}, {"q": "Barato means:", "options": ["New", "Cheap", "Big", "Expensive"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Clothing, Colors, Shopping and Larger Numbers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,1}'::int[], array[$j$Cuesta comes from costar.$j$,$j$Quinientos is five hundred.$j$,$j$The adjective follows the noun and agrees.$j$,$j$Barato is inexpensive.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Clothing, Colors, Shopping and Larger Numbers$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Places in Town, the Verb Ir and Directions$j$, $j${"questions": [{"q": "The nosotros form of ir is:", "options": ["Vemos", "Van", "Vamos", "Vanos"]}, {"q": "A plus el becomes:", "options": ["Al", "Ael", "A el", "Del"]}, {"q": "A la izquierda means:", "options": ["To the left", "Straight ahead", "To the right", "Far away"]}, {"q": "Voy a estudiar means:", "options": ["I am going to study", "I study", "I studied", "I want to study"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Places in Town, the Verb Ir and Directions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,0}'::int[], array[$j$Ir is irregular.$j$,$j$The words contract into al.$j$,$j$Izquierda means left.$j$,$j$Ir a plus an infinitive means going to.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Places in Town, the Verb Ir and Directions$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Food, Shopping and Community$j$, $j${"questions": [{"q": "La cena is:", "options": ["Dinner", "Breakfast", "Lunch", "A drink"]}, {"q": "Les gusta means:", "options": ["You like", "I like", "We like", "They like"]}, {"q": "Ellos quieren comer means:", "options": ["They are eating", "They want to eat", "I want to eat", "They ate"]}, {"q": "Prefiero el té is:", "options": ["He prefers tea", "We prefer tea", "I prefer tea", "You prefer tea"]}, {"q": "Doscientos cincuenta is:", "options": ["205", "2050", "520", "250"]}, {"q": "Los zapatos blancos means:", "options": ["The white shoes", "A white hat", "The black shoes", "The white shirt"]}, {"q": "Vamos al banco means:", "options": ["We have a bank", "I am going to the bank", "We are going to the bank", "They go home"]}, {"q": "To ask where the pharmacy is, say:", "options": ["¿Cuánto cuesta la farmacia?", "¿Cómo se llama?", "¿Dónde está la farmacia?", "¿Qué hora es?"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Food, Shopping and Community$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,2,3,0,2,2}'::int[], array[$j$Cena is dinner.$j$,$j$Les is for they or you all.$j$,$j$Quieren is from querer.$j$,$j$Prefiero is the yo form.$j$,$j$200 plus 50.$j$,$j$Zapatos is shoes and blancos is white.$j$,$j$Vamos is the nosotros form of ir.$j$,$j$Dónde asks where.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Food, Shopping and Community$j$ on conflict (item_id) do nothing;
